/// <summary>
/// PaffH 10.08.21
/// fill logisticsLocation.Description if empty
/// </summary>
/// <param name="sender">nDXLogisticsLocationName1</param>
/// <param name="e">not used</param>
[FormControlEventHandler(formControlStr(LogisticsPostalAddress, NameGroup_NDXLogisticsLocationName1), FormControlEventType::Modified),
    SuppressBPWarning('BPParameterNotUsed', 'The parameter ist not required in this context')]
public static void NameGroup_NDXLogisticsLocationName1_OnModified(FormControl sender, FormControlEventArgs e)
{
    FormRun formRun = sender.formRun() as FormRun;
    FormStringControl nDXLogisticsLocationName1 = sender as FormStringControl;
    FormDataSource  logisticsLocation_ds = formRun.dataSource(formDataSourceStr(LogisticsPostalAddress, LogisticsLocation));
    LogisticsLocation logisticsLocation = logisticsLocation_ds.cursor();
    if (!logisticsLocation.Description)
    {
        logisticsLocation.Description = nDXLogisticsLocationName1.text();
    }
}

/// <summary>
/// PaffH 10.08.21
/// fill logisticsPostalAddress.NDXLogisticsLocationName1 if empty
/// </summary>
/// <param name="sender">details_Description</param>
/// <param name="e">not used</param>
[FormControlEventHandler(formControlStr(LogisticsPostalAddress, Details_Description), FormControlEventType::Modified),
    SuppressBPWarning('BPParameterNotUsed', 'The parameter ist not required in this context')]
public static void Details_Description_OnModified(FormControl sender, FormControlEventArgs e)
{
    FormRun formRun = sender.formRun() as FormRun;
    FormStringControl details_Description = sender as FormStringControl;
    FormDataSource logisticsPostalAddress_ds = formRun.dataSource(FormDataSourceStr(LogisticsPostalAddress, LogisticsPostalAddress));
    LogisticsPostalAddress logisticsPostalAddress = logisticsPostalAddress_ds.cursor();
    if (!logisticsPostalAddress.NDXLogisticsLocationName1)
    {
        logisticsPostalAddress.NDXLogisticsLocationName1 = details_Description.text();
    }
}
